// Pure helpers: reading Claude's limits, briefing Codex, and turning
// `codex exec --json` events into lines of the reply.

export type Limit = { kind: string; percentUsed: number; resetsAt?: string }
export type Brief = { role: 'user' | 'assistant'; text: string; tools: string[] }

export type CodexEvent = {
  threadId?: string
  show?: string
  isActivity?: boolean
  files?: string[]
  error?: string
}

const KIND_LABELS: Record<string, string> = {
  five_hour: '5-hour',
  seven_day: 'weekly',
  spend_limit: 'spend',
}

const MESSAGE_CAP = 4000
const CONTEXT_CAP = 40000
const FIRST_CONTEXT = 20

export function kindLabel(kind: string): string {
  return KIND_LABELS[kind] ?? kind.replaceAll('_', ' ')
}

/** The window that has run out and has not reset yet, if any. */
export function exhausted(limits: readonly Limit[], now: number): Limit | undefined {
  return limits.find(
    limit => limit.percentUsed >= 100 && (limit.resetsAt === undefined || Date.parse(limit.resetsAt) > now),
  )
}

/** The fullest window, for the status line. */
export function fullest(limits: readonly Limit[]): Limit | undefined {
  return [...limits].sort((a, b) => b.percentUsed - a.percentUsed)[0]
}

export function resetLabel(resetsAt: string | undefined): string {
  if (resetsAt === undefined) {
    return 'when it resets'
  }

  const at = new Date(resetsAt)

  if (Number.isNaN(at.getTime())) {
    return 'when it resets'
  }

  const day = at.toLocaleDateString('en-US', { weekday: 'short' })
  const time = at.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })

  return `${day} ${time}`
}

function clip(text: string, cap: number): string {
  return text.length <= cap ? text : `${text.slice(0, cap)} […]`
}

function transcript(briefs: readonly Brief[]): string {
  const lines: string[] = []
  let size = 0

  // Newest first, so the cap drops the oldest messages.
  for (const brief of [...briefs].reverse()) {
    const who = brief.role === 'user' ? 'User' : 'Assistant'
    const tools = brief.tools.length > 0 ? ` (used: ${[...new Set(brief.tools)].join(', ')})` : ''
    const line = `[${who}]${tools}\n${clip(brief.text.trim() || '(no text)', MESSAGE_CAP)}`

    if (size + line.length > CONTEXT_CAP) {
      break
    }

    lines.unshift(line)
    size += line.length
  }

  return lines.join('\n\n')
}

/** What Codex reads: the situation once, then only what it has not seen. */
export function buildPrompt(args: {
  isFirst: boolean
  cwd: string
  why: string
  context: readonly Brief[]
  text: string
}): string {
  const parts: string[] = []

  if (args.isFirst) {
    parts.push(
      `You are taking over a coding conversation from Claude Code in ${args.cwd} because ${args.why}. ` +
        'Continue the work in the same direction. You can read and edit files in this directory. ' +
        'Reply to the user directly and briefly; they read your reply in the same chat.',
    )

    const recent = transcript(args.context.slice(-FIRST_CONTEXT))

    if (recent !== '') {
      parts.push(`The conversation so far, oldest first:\n\n${recent}`)
    }
  } else if (args.context.length > 0) {
    parts.push(`Since your last reply, the conversation went on:\n\n${transcript(args.context)}`)
  }

  parts.push(`The user's new message:\n\n${args.text.trim() || '(continue)'}`)

  return parts.join('\n\n---\n\n')
}

function unwrapShell(command: string): string {
  const found = /^\/bin\/(?:ba|z)?sh -lc '([\s\S]*)'$/.exec(command)

  return (found?.[1] ?? command).replaceAll("'\\''", "'")
}

function inlineCode(text: string): string {
  const flat = text.replace(/\s+/g, ' ').trim()
  const short = flat.length > 120 ? `${flat.slice(0, 117)}…` : flat

  return `\`${short.replaceAll('`', "'")}\``
}

type RawItem = {
  type?: string
  text?: string
  command?: string
  exit_code?: number | null
  changes?: { path?: string; kind?: string }[]
  query?: string
  server?: string
  tool?: string
  message?: string
}

type RawEvent = {
  type?: string
  thread_id?: string
  item?: RawItem
  error?: { message?: string }
  message?: string
}

/** One line of `codex exec --json` output; a line that is not JSON is skipped. */
export function readEvent(line: string): CodexEvent {
  let event: RawEvent

  try {
    event = JSON.parse(line) as RawEvent
  } catch {
    return {}
  }

  if (event.type === 'thread.started' && typeof event.thread_id === 'string') {
    return { threadId: event.thread_id }
  }

  if (event.type === 'turn.failed') {
    return { error: event.error?.message ?? 'Codex stopped with an error' }
  }

  if (event.type === 'error') {
    return { error: event.message ?? 'Codex reported an error' }
  }

  if (event.type !== 'item.completed' || event.item === undefined) {
    return {}
  }

  const item = event.item

  switch (item.type) {
    case 'agent_message':
      return item.text ? { show: item.text } : {}
    case 'command_execution': {
      const failed = typeof item.exit_code === 'number' && item.exit_code !== 0
      const ran = `ran ${inlineCode(unwrapShell(item.command ?? ''))}${failed ? ` (exit ${item.exit_code})` : ''}`

      return { show: ran, isActivity: true }
    }
    case 'file_change': {
      const files = (item.changes ?? []).map(change => change.path ?? '').filter(path => path !== '')
      const verb = (kind: string | undefined) => (kind === 'add' ? 'added' : kind === 'delete' ? 'deleted' : 'edited')
      const lines = (item.changes ?? [])
        .filter(change => change.path)
        .map(change => `${verb(change.kind)} ${inlineCode(change.path ?? '')}`)

      return lines.length > 0 ? { show: lines.join('\n- '), isActivity: true, files } : {}
    }
    case 'web_search':
      return item.query ? { show: `searched the web for ${inlineCode(item.query)}`, isActivity: true } : {}
    case 'mcp_tool_call':
      return { show: `used ${inlineCode(`${item.server ?? 'mcp'}.${item.tool ?? 'tool'}`)}`, isActivity: true }
    case 'error':
      return { error: item.message ?? 'Codex reported an error' }
    default:
      return {}
  }
}

/** The command Nightshift runs: through a login shell, so `codex` and `node` resolve as in a terminal. */
export function codexArgv(
  threadId: string | undefined,
  prompt: string,
  choice: { model?: string; effort?: string; images?: readonly string[]; config?: readonly string[] } = {},
): string[] {
  const codex = threadId === undefined ? ['exec'] : ['exec', 'resume', threadId]
  const model = choice.model === undefined ? [] : ['-m', choice.model]
  const effort = choice.effort === undefined ? [] : ['-c', `model_reasoning_effort="${choice.effort}"`]

  return [
    '/bin/zsh',
    '-lc',
    'exec codex "$@"',
    'codex',
    ...codex,
    '--json',
    '--skip-git-repo-check',
    '-c',
    'sandbox_mode="workspace-write"',
    ...model,
    ...effort,
    ...(choice.config ?? []).flatMap(pair => ['-c', pair]),
    // `--image=` so the prompt after it is never read as one more image.
    ...(choice.images ?? []).map(path => `--image=${path}`),
    prompt,
  ]
}

/**
 * Claude's browser pane offered to a Codex run: the bridge as an MCP server.
 * Codex does not ask before its tools because Nightshift asks in Claude instead
 * (or not, when the user picked Tools: Codex, auto).
 */
export function browserConfig(root: string, socket: string): string[] {
  return [
    'mcp_servers.claude_browser.command="node"',
    `mcp_servers.claude_browser.args=${JSON.stringify([`${root}/hooks/browser-mcp.mjs`, socket])}`,
    'mcp_servers.claude_browser.tool_timeout_sec=180',
    'mcp_servers.claude_browser.default_tools_approval_mode="approve"',
  ]
}

export const BROWSER_NOTE =
  '\n\nFor any web browsing, use the claude_browser tools: they drive the browser pane the user is watching in Claude. ' +
  "Use @chrome only if this brief asks for the user's own Chrome."

export type CodexLimits = { fiveHour?: number; week?: number; weekResetsAt?: number }

const WEEK_MS = 7 * 24 * 60 * 60 * 1000

type RawWindow = { used_percent?: number; window_minutes?: number; resets_at?: number | null } | null | undefined

// Codex has logged the windows a minute either side of their nominal length.
const isWindow = (minutes: number | undefined, nominal: number) =>
  minutes !== undefined && Math.abs(minutes - nominal) <= 60

/** Codex's own windows, from the newest `rate_limits` line of its session logs. */
export function readCodexLimits(line: string, now: number): CodexLimits | undefined {
  let found: { payload?: { rate_limits?: { primary?: RawWindow; secondary?: RawWindow } } }

  try {
    found = JSON.parse(line) as typeof found
  } catch {
    return undefined
  }

  const limits = found.payload?.rate_limits

  if (!limits) {
    return undefined
  }

  const read: CodexLimits = {}

  for (const window of [limits.primary, limits.secondary]) {
    if (!window || typeof window.used_percent !== 'number') {
      continue
    }

    const resetsAt = typeof window.resets_at === 'number' ? window.resets_at * 1000 : undefined
    // A window that has reset since the line was written starts at zero.
    const used = resetsAt !== undefined && resetsAt <= now ? 0 : window.used_percent

    if (isWindow(window.window_minutes, 300)) {
      read.fiveHour = used
    } else if (isWindow(window.window_minutes, 10080)) {
      const week = currentWeek({ week: window.used_percent, weekResetsAt: resetsAt }, now)

      read.week = week.week

      if (week.weekResetsAt !== undefined) {
        read.weekResetsAt = week.weekResetsAt
      }
    }
  }

  return read
}

/**
 * Codex's 7-day window as it stands at `now`: once the read window has reset,
 * the next one has begun at zero and resets a week on. The strip asks at each
 * draw, so an idle session never shows a reset time that has passed.
 */
export function currentWeek(limits: CodexLimits | undefined, now: number): Pick<CodexLimits, 'week' | 'weekResetsAt'> {
  let resetsAt = limits?.weekResetsAt

  if (limits?.week === undefined || resetsAt === undefined || resetsAt > now) {
    return { week: limits?.week, weekResetsAt: resetsAt }
  }

  while (resetsAt <= now) {
    resetsAt += WEEK_MS
  }

  return { week: 0, weekResetsAt: resetsAt }
}

/** How far into its 7-day window Codex's limit is, 0 to 1, from when it resets. */
export function weekElapsed(resetsAt: number | undefined, now: number): number | undefined {
  if (resetsAt === undefined) {
    return undefined
  }

  return Math.min(1, Math.max(0, 1 - (resetsAt - now) / WEEK_MS))
}

/** `5h 3% · 7d 15%`: short enough for the line under the box. */
export function windows(fiveHour: number | undefined, week: number | undefined): string {
  const parts = [
    fiveHour === undefined ? undefined : `5h ${Math.round(fiveHour)}%`,
    week === undefined ? undefined : `7d ${Math.round(week)}%`,
  ].filter(part => part !== undefined)

  return parts.join(' · ')
}

/** The script Nightshift runs to find that line, newest logs first. */
// The newest log that has a reading, and its last one: newest file first,
// since grep would print an older file's lines after a newer one's.
export const CODEX_LIMITS_SCRIPT =
  'setopt nullglob; cd ~/.codex/sessions 2>/dev/null || exit 0; ' +
  'for file in $(ls -t */*/*/*.jsonl 2>/dev/null | head -8); do ' +
  'line=$(grep -h \'"rate_limits":{\' $file 2>/dev/null | tail -1); ' +
  '[[ -n $line ]] && { print -r -- $line; exit 0 }; done'

export type CodexModel = { slug: string; name: string; efforts?: string[] }

/** The models Codex lists, from its own cache (`~/.codex/models_cache.json`). */
export function readModels(cache: string): CodexModel[] {
  try {
    const parsed = JSON.parse(cache) as {
      models?: {
        slug?: string
        display_name?: string
        visibility?: string
        supported_reasoning_levels?: { effort?: string }[]
      }[]
    }

    return (parsed.models ?? [])
      .filter(model => model.visibility === 'list' && typeof model.slug === 'string')
      .map(model => ({
        slug: model.slug ?? '',
        name: model.display_name ?? model.slug ?? '',
        efforts: model.supported_reasoning_levels?.map(level => level.effort ?? '').filter(effort => effort !== ''),
      }))
  } catch {
    return []
  }
}

/** `model = "..."` and `model_reasoning_effort = "..."` from `~/.codex/config.toml`. */
export function readCodexDefaults(toml: string): { model?: string; effort?: string } {
  const value = (key: string) => new RegExp(`^${key}\\s*=\\s*"([^"]+)"`, 'm').exec(toml)?.[1]

  return { model: value('model'), effort: value('model_reasoning_effort') }
}

// Only the two top-level settings Nightshift uses leave config.toml: the file can
// hold other tools' secrets further down.
export const CODEX_SETUP_SCRIPT =
  'cat ~/.codex/models_cache.json 2>/dev/null; printf "\\n@@config@@\\n"; ' +
  "awk '/^\\[/{exit} /^(model|model_reasoning_effort)[ \\t]*=/' ~/.codex/config.toml 2>/dev/null"

files.hooks/look.ts:
// What Nightshift draws with: the Codex CLI's logo (codex-frames.ts) as a still dot
// matrix, its working-line shimmer, and a Codex reply read back into its
// header, its steps and its words.

import { FRAMES } from './codex-frames'

export const HEADER = '**Codex**'

const INK = '#ecebe6'
// The strip's own background, which dim text fades toward.
const STRIP = '#262624'

// Braille dot order: bit n of a cell is this (column, row) within its 2×4 dots.
const DOT_AT: readonly (readonly [number, number])[] = [[0, 0], [0, 1], [0, 2], [1, 0], [1, 1], [1, 2], [0, 3], [1, 3]]

/**
 * The Codex CLI's Braille logo at rest as a dot matrix: every dot its renderer
 * lit, in its cell's color, `height` pixels tall. It never moves.
 */
export function logoDots(height: number): { source: string; width: number } {
  const rows = FRAMES[0] ?? []
  const columns = [...(rows[0]?.[0] ?? '')].length
  const step = height / (rows.length * 4)
  const width = Math.round(step * columns * 2)
  const radius = (step * 0.42).toFixed(2)
  const dots: string[] = []

  rows.forEach(([text, colors], row) => {
    const palette = colors.split(',')

    ;[...text].forEach((char, column) => {
      const bits = (char.codePointAt(0) ?? 0x2800) - 0x2800

      DOT_AT.forEach(([dx, dy], bit) => {
        if (bits & (1 << bit)) {
          const x = ((column * 2 + dx + 0.5) * step).toFixed(2)
          const y = ((row * 4 + dy + 0.5) * step).toFixed(2)

          dots.push(`<circle cx="${x}" cy="${y}" r="${radius}" fill="${palette[column] ?? INK}"/>`)
        }
      })
    })
  })

  return {
    source: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}">${dots.join('')}</svg>`,
    width,
  }
}

function mix(a: string, b: string, share: number): string {
  const channel = (hex: string, at: number) => parseInt(hex.slice(1 + at * 2, 3 + at * 2), 16)

  return `#${[0, 1, 2].map(at => Math.round(channel(a, at) * share + channel(b, at) * (1 - share)).toString(16).padStart(2, '0')).join('')}`
}

/**
 * Each character's color in the working line, as the Codex CLI's
 * summary_shimmer.rs computes it: a band at least 3 characters wide crosses
 * the words in 1s every 4s after 0.6s, from half ink to full ink.
 */
export function shimmerColors(text: string, elapsed: number): string[] {
  const chars = [...text]
  const half = Math.max(chars.length * 0.1, 3)
  const sweep = Math.min(Math.max(0, elapsed - 600) % 4000, 1000) / 1000
  const position = sweep * (chars.length + 2 * half) - half

  return chars.map((_, at) => {
    const distance = Math.min(Math.abs(at + 0.5 - position) / half, 1)
    const intensity = 0.5 * (1 + Math.cos(Math.PI * distance))

    return mix(INK, STRIP, 0.5 + 0.5 * intensity)
  })
}

/** The working bullet's color: it brightens as its own 2s shimmer passes, as motion.rs draws it. */
export function bulletColor(elapsed: number): string {
  const position = ((elapsed % 2000) / 2000) * 21
  const distance = Math.abs(10 - position)
  const intensity = distance <= 5 ? 0.5 * (1 + Math.cos((Math.PI * distance) / 5)) : 0

  return mix(INK, STRIP, 0.5 + 0.5 * intensity)
}

export type Step = { glyph: string; text: string; isFailed: boolean }
export type Reply = { steps: Step[]; words: string }

const STEP = /^- (ran|edited|added|deleted|searched the web for|used) (.+)$/

const GLYPHS: Record<string, string> = {
  ran: '$',
  edited: '✎',
  added: '+',
  deleted: '−',
  'searched the web for': '⌕',
  used: '⚙',
}

const LABELS: Record<string, string> = {
  ran: 'Ran',
  edited: 'Edited',
  added: 'Added',
  deleted: 'Deleted',
  'searched the web for': 'Searched',
  used: 'Used',
}

export function isCodexReply(text: string): boolean {
  return text.trimStart().startsWith(HEADER)
}

/** Splits a Codex reply into its step rows and the rest, kept as markdown. */
export function readReply(text: string): Reply {
  const body = text.trimStart().slice(HEADER.length)
  const steps: Step[] = []
  const words: string[] = []

  for (const line of body.split('\n')) {
    const found = STEP.exec(line.trim())

    if (found) {
      const verb = found[1] ?? 'ran'
      const rest = (found[2] ?? '').replaceAll('`', '')

      steps.push({
        glyph: GLYPHS[verb] ?? '·',
        text: `${LABELS[verb] ?? verb} ${rest.replace(/ \(exit \d+\)$/, '')}`,
        isFailed: / \(exit \d+\)$/.test(rest),
      })
    } else {
      words.push(line)
    }
  }

  return { steps, words: words.join('\n').trim() }
}

/** `Running npm test`: the live line while Codex works, from one step. */
export function liveLine(step: string): string {
  const found = STEP.exec(`- ${step}`)

  if (!found) {
    return 'Thinking'
  }

  const rest = (found[2] ?? '').replaceAll('`', '').replace(/ \(exit \d+\)$/, '')
  const verbs: Record<string, string> = {
    ran: 'Running',
    edited: 'Editing',
    added: 'Adding',
    deleted: 'Deleting',
    'searched the web for': 'Searching',
    used: 'Using',
  }

  return `${verbs[found[1] ?? ''] ?? 'Working on'} ${rest}`
}

export function duration(ms: number): string {
  const seconds = Math.max(0, Math.round(ms / 1000))

  return seconds < 60 ? `${seconds}s` : `${Math.floor(seconds / 60)}m ${seconds % 60}s`
}

// Codex's reasoning levels as the strip offers them, lightest first.
export const CODEX_EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max'] as const
export type CodexEffort = (typeof CODEX_EFFORTS)[number]

export const EFFORT_LABELS: Record<CodexEffort, string> = {
  low: 'Light',
  medium: 'Medium',
  high: 'High',
  xhigh: 'XHigh',
  max: 'Max',
}

/**
 * The levels a model takes, from what its cache entry lists; every level when
 * the cache says nothing.
 */
export function effortsFor(supported: readonly string[] | undefined): CodexEffort[] {
  const known = CODEX_EFFORTS.filter(effort => supported === undefined || supported.includes(effort))

  return known.length > 0 ? known : [...CODEX_EFFORTS]
}

/** The chosen level, or the closest one below it that the model takes. */
export function effortWithin(chosen: CodexEffort, offered: readonly CodexEffort[]): CodexEffort {
  const at = CODEX_EFFORTS.indexOf(chosen)
  const below = offered.filter(effort => CODEX_EFFORTS.indexOf(effort) <= at)

  return below.at(-1) ?? offered[0] ?? chosen
}

// The Codex 7-day limit as a week of square tiles, read like a battery: the
// share left lit in the logo's ink, full at 100% and empty at 0%, and a faint
// tick where the week's remaining time ends, so lit tiles past the tick mean
// more left than the week needs. One static SVG, 26px tall.
const LIMIT_FONT = '-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif'
const LIMIT_TEXT = '#ecebe6'
const LIMIT_DIM = '#8a8984'
const LIMIT_LIT = '#d4d4ce'
const LIMIT_UNLIT = '#3a3936'
const LIMIT_TICK = '#74736d'
// From 75% the lit tiles warm to honey; from 90% they turn a soft red.
const LIMIT_WARM = '#d9b779'
const LIMIT_HOT = '#e36d5d'

// Measured with the strip's font: "100%" at 12.5px semibold is 37px wide,
// "Wed 22:59" at 11px about 58px.
const PERCENT_RESERVE = 38
const RESET_RESERVE = 58
const GAP_TILES_TEXT = 8
const GAP_TEXT_RESET = 10
// Room left of the first tile for the "now" tick at the start of the week.
const TICK_ROOM = 2
// Narrower than this, the reset time gives way to the tiles.
const MIN_RESET_WIDTH = 280

type TileGrid = { tile: number; gap: number; groupGap: number; perDay: number; day: number; span: number; count: number }

const clampTo = (value: number, low: number, high: number) => Math.min(high, Math.max(low, value))

/**
 * The week's grid that best fills `space`: 7 day groups of whole-pixel square
 * tiles, the most per day that fit, then the larger tile; the gap between
 * days clearly wider than inside one. Left-over room sits on the left.
 */
function tileGrid(space: number): TileGrid {
  let best: TileGrid | undefined

  for (const tile of [8, 7, 6]) {
    if (tile === 6 && best !== undefined) {
      break
    }

    const gap = 3

    for (let perDay = 2; perDay <= 5; perDay++) {
      const day = perDay * tile + (perDay - 1) * gap
      const groupGap = Math.min(12, Math.floor((space - 7 * day) / 6))

      if (groupGap < 7) {
        continue
      }

      if (best === undefined || perDay > best.perDay) {
        best = { tile, gap, groupGap, perDay, day, span: 7 * day + 6 * groupGap, count: 7 * perDay }
      }
    }

    if (best !== undefined && tile === 8 && best.perDay >= 3) {
      break
    }
  }

  return best ?? { tile: 6, gap: 3, groupGap: 7, perDay: 1, day: 6, span: 7 * 6 + 6 * 7, count: 7 }
}

// Wide enough for 8px tiles, three a day, beside "100%" and the reset time.
export const LIMIT_WIDTH = 368

/** The limit meter's SVG: `percent` used (drawn as what is left), `elapsed` of the week gone (0–1), and the reset label. */
export function limitTiles(args: { percent: number; elapsed?: number; reset?: string; width?: number }): {
  source: string
  width: number
} {
  const width = args.width ?? LIMIT_WIDTH
  const height = 26
  const used = clampTo(Number.isFinite(args.percent) ? args.percent : 0, 0, 100)
  const showReset = args.reset !== undefined && args.reset !== '' && width >= MIN_RESET_WIDTH
  const tilesRight = width - PERCENT_RESERVE - GAP_TILES_TEXT - (showReset ? RESET_RESERVE + GAP_TEXT_RESET : 0)
  const grid = tileGrid(tilesRight - TICK_ROOM)
  const left = tilesRight - grid.span
  const baseline = 17.5
  // Tiles stand on the text's baseline and reach about its cap height.
  const top = 9 + (8 - grid.tile)

  const remaining = 100 - used
  // Anything left lights one tile; only an untouched limit lights them all.
  const lit =
    remaining <= 0 ? 0 : remaining >= 100 ? grid.count : clampTo(Math.round((remaining / 100) * grid.count), 1, grid.count - 1)
  const ink = used >= 90 ? LIMIT_HOT : used >= 75 ? LIMIT_WARM : LIMIT_LIT
  const xOf = (index: number) =>
    left + Math.floor(index / grid.perDay) * (grid.day + grid.groupGap) + (index % grid.perDay) * (grid.tile + grid.gap)
  const radius = grid.tile >= 7 ? 1.5 : 1.25
  const parts: string[] = []

  for (let index = 0; index < grid.count; index++) {
    parts.push(
      `<rect x="${xOf(index)}" y="${top}" width="${grid.tile}" height="${grid.tile}" rx="${radius}" fill="${index < lit ? ink : LIMIT_UNLIT}"/>`,
    )
  }

  // The week's time left, snapped to the nearest tile edge so it never cuts a tile.
  if (args.elapsed !== undefined) {
    const boundary = Math.round((1 - clampTo(args.elapsed, 0, 1)) * grid.count)
    const tickX =
      boundary <= 0
        ? left - 2
        : boundary >= grid.count
          ? tilesRight + 2
          : (xOf(boundary - 1) + grid.tile + xOf(boundary)) / 2

    parts.push(`<rect x="${Math.round(tickX - 0.5)}" y="${top - 4}" width="1" height="${grid.tile + 8}" rx="0.5" fill="${LIMIT_TICK}"/>`)
  }

  const numbers = 'font-variant-numeric:tabular-nums'

  parts.push(
    `<text x="${tilesRight + GAP_TILES_TEXT}" y="${baseline}" font-family="${LIMIT_FONT}" font-size="12.5" font-weight="600" fill="${used >= 90 ? LIMIT_HOT : LIMIT_TEXT}" style="${numbers}">${Math.round(remaining)}%</text>`,
  )

  if (showReset) {
    parts.push(
      `<text x="${width}" y="${baseline}" text-anchor="end" font-family="${LIMIT_FONT}" font-size="11" fill="${LIMIT_DIM}" style="${numbers}">${(args.reset ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')}</text>`,
    )
  }

  return {
    source: `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${parts.join('')}</svg>`,
    width,
  }
}

