// Generated from the Codex CLI's own logo renderer (openai/codex, Apache-2.0;
// see NOTICE): codex-rs/tui/src/empty_state_animation, ported line for line
// and run at 20 columns by 7 rows: the Codex mark at rest, its first frame.
// Each row is its Braille characters and each character's color ('' blank).
// Regenerate rather than edit.

export const FRAME_COLUMNS = 20
